int berechneNachlieferung(int sollBestand, int istBestand) {
    int ergebnis = -1;
    if (sollBestand >= 0 && istBestand >= 0) {
        if (istBestand <= sollBestand) {
            ergebnis = sollBestand - istBestand;
        }
    }
    return ergebnis;
}

private WebResponse erstelleAblehnung(string meldung, int status) {
    WebResponse antwort = new WebResponse(status);
    antwort.setHeader("Content-Type", "text/plain; charset=utf-8");
    int laenge = TextCodec.utf8ByteLength(meldung);
    antwort.setHeader("Content-Length", Integer.toString(laenge));
    antwort.setBody(meldung);
    return antwort;
}

private HttpResponse createRejectResponse(string reason, int status) {
    HttpResponse response = new HttpResponse(status);
    response.addHeader("Content-Type", "text/plain; charset=utf-8");
    response.addHeader("Content-Length", String.valueOf(Utf8.byteLength(reason)));
    response.setBody(reason);
    return response;
}
